-- yields inside an xpcall message handler are refused by stock
print(coroutine.wrap(function()
  return xpcall(function() error('e', 0) end, function(m)
    local r = coroutine.yield('inh')
    return m .. tostring(r)
  end)
end)())
print(coroutine.wrap(function()
  return xpcall(function() error('e', 0) end, coroutine.yield)
end)())
print(coroutine.wrap(function()
  return xpcall(function() error('e', 0) end, function(m)
    return coroutine.isyieldable()
  end)
end)())
